5	const runCli = (stdin: string): Promise<{ status: number; stdout: string; stderr: string }> =>
6	  new Promise((resolve) => {
7	    const cli = spawn("npx", ["tsx", "src/cli.ts"]);
8	    let stdout = "";
9	    let stderr = "";
10	    cli.stdout.on("data", (chunk) => (stdout += chunk));
11	    cli.stderr.on("data", (chunk) => (stderr += chunk));
12	    cli.on("close", (status) => resolve({ status: status ?? 1, stdout, stderr }));
13	    cli.stdin.end(stdin);
14	  });
