// A claim names its policy by the index of the step that created it, so
// policies are keyed by step index rather than pushed: claim steps simply leave
// no entry. Results are pushed in step order, so the two stay aligned.
export const runScenario = (scenario: Scenario): ScenarioResults => {
  const results: Result[] = [];
  const policies: Policy[] = [];
  let contractsIssued = 0;
  for (const [stepIndex, step] of scenario.steps.entries()) {
    if (step.op === "claim") {
      results.push(claimFor(step, policies));
      continue;
    }
    results.push(
      quoteFor(step, {
        customer: scenario.customer,
        previousContracts: contractsIssued,
      }),
    );
    policies[stepIndex] = policyFor(step);
    contractsIssued += 1;
  }
  return { results };
};

